  "guardian.battery": { en: "Battery", hi: "बैटरी", bn: "ব্যাটারি", ta: "பேட்டரி", te: "బ్యాటరీ", mr: "बॅटरी" },
  "guardian.unavailable": { en: "Unavailable", hi: "अनुपलब्ध", bn: "অনুপলব্ধ", ta: "கிடைக்கவில்லை", te: "అందుబాటులో లేదు", mr: "अनुपलब्ध" },
