  "guardian.intelligentAlerts": { en: "Intelligent alerts", hi: "स्मार्ट अलर्ट", bn: "বুদ্ধিমান সতর্কতা", ta: "அறிவார்ந்த எச்சரிக்கைகள்", te: "తెలివైన హెచ్చరికలు", mr: "स्मार्ट सूचना" },
  "guardian.noAlerts": { en: "No alerts — journey is proceeding normally.", hi: "कोई अलर्ट नहीं — यात्रा सामान्य रूप से चल रही है।", bn: "কোনো সতর্কতা নেই — যাত্রা স্বাভাবিকভাবে চলছে।", ta: "எச்சரிக்கைகள் இல்லை — பயணம் இயல்பாக நடைபெறுகிறது.", te: "హెచ్చరికలు లేవు — ప్రయాణం సాధారణంగా కొనసాగుతోంది.", mr: "सूचना नाहीत — प्रवास सामान्यपणे सुरू आहे." },
  "guardian.currentStatus": { en: "Current status", hi: "वर्तमान स्थिति", bn: "বর্তমান অবস্থা", ta: "தற்போதைய நிலை", te: "ప్రస్తుత స్థితి", mr: "सध्याची स्थिती" },

  // ---- alerts page ----
  "alerts.subtitle": { en: "SOS triggers, route deviations, and safety check-in misses show up here.", hi: "एसओएस ट्रिगर, मार्ग विचलन और सुरक्षा चेक-इन मिस यहां दिखाई देते हैं।", bn: "এসওএস ট্রিগার, রুট বিচ্যুতি এবং নিরাপত্তা চেক-ইন মিস এখানে দেখা যায়।", ta: "எஸ்ஓஎஸ் தூண்டுதல்கள், பாதை விலகல்கள் மற்றும் பாதுகாப்பு செக்-இன் தவறவிட்டவை இங்கே தோன்றும்.", te: "ఎస్ఓఎస్ ట్రిగ్గర్‌లు, మార్గం విచలనాలు మరియు భద్రతా చెక్-ఇన్ మిస్‌లు ఇక్కడ కనిపిస్తాయి.", mr: "एसओएस ट्रिगर, मार्ग विचलन आणि सुरक्षा चेक-इन चुकणे येथे दिसतात." },
  "alerts.history": { en: "Alert history", hi: "अलर्ट इतिहास", bn: "সতর্কতা ইতিহাস", ta: "எச்சரிக்கை வரலாறு", te: "హెచ్చరిక చరిత్ర", mr: "सूचना इतिहास" },
  "alerts.noAlertsYet": { en: "No alerts yet", hi: "अभी तक कोई अलर्ट नहीं", bn: "এখনো কোনো সতর্কতা নেই", ta: "இதுவரை எச்சரிக்கைகள் இல்லை", te: "ఇంకా హెచ్చరికలు లేవు", mr: "अद्याप सूचना नाहीत" },
  "alerts.noAlertsDesc": { en: "You'll see a record here the moment an SOS is triggered, a journey deviates from its planned route, or a safety check-in is missed.", hi: "जैसे ही कोई एसओएस ट्रिगर होता है, कोई यात्रा अपने नियोजित मार्ग से विचलित होती है, या कोई सुरक्षा चेक-इन छूट जाता है, आपको यहां एक रिकॉर्ड दिखाई देगा।", bn: "একটি এসওএস ট্রিগার হওয়ার মুহূর্তে, একটি যাত্রা তার পরিকল্পিত পথ থেকে বিচ্যুত হলে, বা একটি নিরাপত্তা চেক-ইন মিস হলে আপনি এখানে একটি রেকর্ড দেখতে পাবেন।", ta: "எஸ்ஓஎஸ் தூண்டப்படும் தருணத்திலோ, ஒரு பயணம் அதன் திட்டமிடப்பட்ட பாதையிலிருந்து விலகும்போதோ, அல்லது பாதுகாப்பு செக்-இன் தவறவிடப்படும்போதோ இங்கே ஒரு பதிவைக் காண்பீர்கள்.", te: "ఎస్ఓఎస్ ప్రేరేపించబడిన క్షణంలో, ఒక ప్రయాణం దాని ప్రణాళికాబద్ధమైన మార్గం నుండి వైదొలగినప్పుడు, లేదా భద్రతా చెక్-ఇన్ మిస్ అయినప్పుడు మీరు ఇక్కడ ఒక రికార్డును చూస్తారు.", mr: "एसओएस ट्रिगर होताच, प्रवास त्याच्या नियोजित मार्गापासून विचलित झाल्यास, किंवा सुरक्षा चेक-इन चुकल्यास तुम्हाला येथे एक नोंद दिसेल." },

