  // ---- landing / hero ----
  "landing.heroBadge": { en: "AI risk prediction · live in 40+ cities", hi: "एआई जोखिम भविष्यवाणी · 40+ शहरों में लाइव", bn: "এআই ঝুঁকি পূর্বাভাস · ৪০+ শহরে লাইভ", ta: "AI ஆபத்து முன்கணிப்பு · 40+ நகரங்களில் நேரடியாக", te: "AI రిస్క్ ప్రిడిక్షన్ · 40+ నగరాల్లో లైవ్", mr: "एआय जोखीम अंदाज · 40+ शहरांमध्ये लाइव्ह" },
  "landing.heroTitleLine1": { en: "Safety that predicts", hi: "सुरक्षा जो भविष्यवाणी करती है", bn: "নিরাপত্তা যা পূর্বাভাস দেয়", ta: "முன்னறிவிக்கும் பாதுகாப்பு", te: "అంచనా వేసే భద్రత", mr: "अंदाज घेणारी सुरक्षा" },
  "landing.heroTitleLine2": { en: "the danger before it arrives.", hi: "खतरे को उसके आने से पहले।", bn: "বিপদ আসার আগেই।", ta: "ஆபத்து வருவதற்கு முன்பே.", te: "ప్రమాదం రాకముందే.", mr: "धोका येण्यापूर्वीच." },
  "landing.heroDesc": { en: "Suraksha360 is the AI-powered urban safety platform that scores every route before you walk it, watches over your commute in real time, and closes the loop from silent SOS to verified police response — in under 90 seconds.", hi: "सुरक्षा360 एआई-संचालित शहरी सुरक्षा प्लेटफॉर्म है जो आपके चलने से पहले हर मार्ग को स्कोर करता है, वास्तविक समय में आपकी यात्रा पर नज़र रखता है, और साइलेंट एसओएस से सत्यापित पुलिस प्रतिक्रिया तक — 90 सेकंड से भी कम समय में लूप को बंद करता है।", bn: "সুরক্ষা৩৬০ হল এআই-চালিত শহুরে নিরাপত্তা প্ল্যাটফর্ম যা আপনি হাঁটার আগে প্রতিটি রুট স্কোর করে, রিয়েল টাইমে আপনার যাতায়াতের উপর নজর রাখে, এবং নীরব এসওএস থেকে যাচাইকৃত পুলিশ প্রতিক্রিয়া পর্যন্ত লুপ বন্ধ করে — ৯০ সেকেন্ডেরও কম সময়ে।", ta: "சுரக்ஷா360 என்பது நீங்கள் நடப்பதற்கு முன் ஒவ்வொரு பாதையையும் மதிப்பிடும், நிகழ்நேரத்தில் உங்கள் பயணத்தைக் கண்காணிக்கும், மற்றும் அமைதியான எஸ்ஓஎஸ் முதல் சரிபார்க்கப்பட்ட காவல்துறை பதில் வரை — 90 வினாடிகளுக்குள் சுழற்சியை மூடும் AI-இயங்கும் நகர்ப்புற பாதுகாப்பு தளமாகும்.", te: "సురక్ష360 అనేది మీరు నడవడానికి ముందు ప్రతి మార్గాన్ని స్కోర్ చేసే, రియల్ టైమ్‌లో మీ ప్రయాణాన్ని గమనించే, మరియు నిశ్శబ్ద ఎస్ఓఎస్ నుండి ధృవీకరించబడిన పోలీసు ప్రతిస్పందన వరకు — 90 సెకన్లలోపు లూప్‌ను మూసివేసే AI-ఆధారిత పట్టణ భద్రతా వేదిక.", mr: "सुरक्षा360 हे एआय-चालित शहरी सुरक्षा प्लॅटफॉर्म आहे जे तुम्ही चालण्यापूर्वी प्रत्येक मार्गाला गुण देते, रिअल टाइममध्ये तुमच्या प्रवासावर लक्ष ठेवते, आणि सायलेंट एसओएस पासून पडताळणी केलेल्या पोलिस प्रतिसादापर्यंत — 90 सेकंदांपेक्षा कमी वेळात लूप बंद करते." },
  "landing.startSafeJourney": { en: "Start a safe journey", hi: "सुरक्षित यात्रा शुरू करें", bn: "একটি নিরাপদ যাত্রা শুরু করুন", ta: "பாதுகாப்பான பயணத்தைத் தொடங்குங்கள்", te: "సురక్షిత ప్రయాణం ప్రారంభించండి", mr: "सुरक्षित प्रवास सुरू करा" },
  "landing.seeItInAction": { en: "See it in action", hi: "इसे क्रिया में देखें", bn: "এটি কার্যকরভাবে দেখুন", ta: "இதைச் செயலில் பாருங்கள்", te: "దీన్ని చర్యలో చూడండి", mr: "हे कृतीत पहा" },
  "landing.heroBadgeEncrypted": { en: "AES-256 encrypted evidence", hi: "AES-256 एन्क्रिप्टेड साक्ष्य", bn: "AES-256 এনক্রিপ্টেড প্রমাণ", ta: "AES-256 குறியாக்கம் செய்யப்பட்ட ஆதாரம்", te: "AES-256 ఎన్‌క్రిప్ట్ చేసిన సాక్ష్యం", mr: "AES-256 एनक्रिप्टेड पुरावा" },
  "landing.heroBadgeControlRoom": { en: "24/7 control room monitoring", hi: "24/7 नियंत्रण कक्ष निगरानी", bn: "২৪/৭ নিয়ন্ত্রণ কক্ষ পর্যবেক্ষণ", ta: "24/7 கட்டுப்பாட்டு அறை கண்காணிப்பு", te: "24/7 నియంత్రణ గది పర్యవేక్షణ", mr: "24/7 नियंत्रण कक्ष देखरेख" },
  "landing.heroBadgeRouteScoring": { en: "Route + transit safety scoring", hi: "मार्ग + परिवहन सुरक्षा स्कोरिंग", bn: "রুট + ট্রানজিট নিরাপত্তা স্কোরিং", ta: "பாதை + போக்குவரத்து பாதுகாப்பு மதிப்பீடு", te: "మార్గం + రవాణా భద్రతా స్కోరింగ్", mr: "मार्ग + वाहतूक सुरक्षा गुणांकन" },

