  "landing.footerDataPolicy": { en: "Data Policy", hi: "डेटा नीति", bn: "ডেটা নীতি", ta: "தரவு கொள்கை", te: "డేటా విధానం", mr: "डेटा धोरण" },
  "landing.footerRights": { en: "All rights reserved.", hi: "सर्वाधिकार सुरक्षित।", bn: "সর্বস্বত্ব সংরক্ষিত।", ta: "அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.", te: "అన్ని హక్కులు కలిగి ఉన్నాయి.", mr: "सर्व हक्क राखीव." },
  "landing.footerChallenge": { en: "Built for the International Innovation Challenge — Round 2.", hi: "इंटरनेशनल इनोवेशन चैलेंज — राउंड 2 के लिए बनाया गया।", bn: "আন্তর্জাতিক উদ্ভাবন চ্যালেঞ্জ — রাউন্ড ২ এর জন্য তৈরি।", ta: "சர்வதேச புதுமை சவால் — சுற்று 2 க்காக உருவாக்கப்பட்டது.", te: "అంతర్జాతీయ ఇన్నోవేషన్ ఛాలెంజ్ — రౌండ్ 2 కోసం నిర్మించబడింది.", mr: "आंतरराष्ट्रीय नवोपक्रम आव्हान — फेरी 2 साठी तयार केले." },

